const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const C = JSON.parse(await fs.readFile(S+"\\_GIG_CLEAN_FINAL.json","utf8"));

// 重新生成书签
const esc = s => String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
const ts = Math.floor(Date.now()/1000);
const bm = ['<!DOCTYPE NETSCAPE-Bookmark-file-1>','<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">','<TITLE>Bookmarks</TITLE>','<H1>Bookmarks</H1>','<DL><p>'];
bm.push('    <DT><H3 ADD_DATE="'+ts+'">接散活平台 '+C.total+' 个</H3>');
bm.push('    <DL><p>');
for (const [cat, items] of Object.entries(C.groups).sort((a,b)=>b[1].length-a[1].length)) {
  const cc = cat.replace(/[🌍🧪🎓💰📝✍️🌐🤖💼📍🎨🇨🇳]/g,'').trim()||"其他";
  bm.push('        <DT><H3 ADD_DATE="'+ts+'">'+esc(cc)+' ('+items.length+')</H3>');
  bm.push('        <DL><p>');
  for (const it of items) bm.push('            <DT><A HREF="'+esc(it.url||("https://"+it.host))+'">'+esc((it.group==="能看到活"?"[A] ":"[B] ")+it.name)+'</A>');
  bm.push('        </DL><p>');
}
bm.push('    </DL><p>','</DL><p>');
await fs.writeFile(P2+"\\接散活平台书签-"+C.total+"个.html", bm.join("\n"), "utf8");

// 最终报告
const rows=[]; const add=s=>rows.push(s);
add("---"); add("date: 2026-10-21"); add("tags: [工作, 搞钱, 接散活, 71个, 质量审计, 最终版]"); add("---"); add("");
add("# 接散活平台最终清单 · "+C.total+" 个（全部通过质量审计）");
add("");
add("> **目标：50 个真实可接活的平台。**");
add("> **交付："+C.total+" 个，并且逐个做了「这是接散活还是找全职」的审计。**");
add("> **剔除 4 个招聘性质强的，剩下 "+C.total+" 个都是能接活/接项目的。**");
add("");
add("## 一、⭐⭐ 这轮做了什么审计");
add("");
add("**问题**：之前的清单里混进了招聘板（比如 Dribbble Jobs 主要是全职设计岗）。");
add("");
add("**做法**：逐个判断——这个平台是「你干完一单就收钱」，还是「你去应聘一个岗位」？");
add("");
add("| 判定标准 | 保留 | 剔除 |");
add("|---|---|---|");
add("| **接散活** | 按项目/按次/按小时结算，干完就完 | ✅ | |");
add("| **找全职** | 需要长期雇佣、排班、五险一金 | | ❌ |");
add("");
add("### 被剔除的 4 个（诚实列出）");
add("");
add("| 平台 | 为什么剔除 |");
add("|---|---|");
for (const e of C.excluded) add("| "+e.name+" | "+e.why+" |");
add("");
add("## 二、⭐⭐ "+C.total+" 个平台完整清单");
add("");
let i=1;
for (const [cat, items] of Object.entries(C.groups).sort((a,b)=>b[1].length-a[1].length)) {
  add("### "+cat+"（"+items.length+" 个）");
  add("");
  add("| # | 平台 | 网址 | 级别 | 怎么接活 |");
  add("|---|---|---|---|---|");
  for (const it of items) {
    const how = it.group==="能看到活" ? (it.cards?it.cards+"个项目可见":"列表可见") : "注册后可见";
    add("| "+i+" | **"+it.name+"** | "+it.host+" | "+(it.group==="能看到活"?"A":"B")+" | "+how+" |");
    i++;
  }
  add("");
}
add("## 三、⭐⭐ 三种接活模式（按你怎么干分类）");
add("");
add("| 模式 | 怎么运作 | 平台 |");
add("|---|---|---|");
add("| **① 投标抢单** | 看到项目→报价→客户选你→干活收钱 | Freelancer、Upwork、Toptal、Fiverr、猪八戒、一品威客、程序员客栈、猿急送、实现网、我爱方案网、智城外包 |");
add("| **② 挂服务等客** | 发布服务→客户直接下单→交付 | Fiverr、有道人工翻译、99designs、DesignCrowd、Working Not Working |");
add("| **③ 接任务流水线** | 平台派单/任务池→你接→按件结算 | Clickworker、Prolific、Scribie、GoTranscript、Toloka、Microworkers、Figure Eight、百度众测、收奖网 |");
add("");
add("**你要「多个平台同时看着」，最适合的是 ①+③：投标 + 任务池。**");
add("");
add("## 四、⭐⭐ 今天开工的具体路径");
add("");
add("### 路线 A：中文（不用翻墙，人民币结算）");
add("");
add("| 步骤 | 平台 | 动作 |");
add("|---|---|---|");
add("| 1 | **一品威客** | 注册→看「设计/文案/开发」分类→投2个标 |");
add("| 2 | **程序员客栈** | 注册→填技能→接技术单 |");
add("| 3 | **猪八戒** | 注册→看企业服务单 |");
add("| 4 | **猿急送** | 注册→接外包 |");
add("| 5 | **有道人工翻译** | 注册译者→接翻译单 |");
add("");
add("### 路线 B：国际（要能翻墙 + 基础英语）");
add("");
add("| 步骤 | 平台 | 动作 |");
add("|---|---|---|");
add("| 1 | **Clickworker** | 注册→做微任务（当天见钱） |");
add("| 2 | **Prolific** | 注册→接调研（$5-20/次） |");
add("| 3 | **Scribie** | 注册→接转录 |");
add("| 4 | **Smartcat** | 注册→接翻译 |");
add("| 5 | **Freelancer** | 注册→投标 |");
add("");
add("## 五、⭐ 按「多久能见第一笔钱」排序");
add("");
add("| 时间 | 平台 | 门槛 |");
add("|---|---|---|");
add("| **当天** | Clickworker、Prolific、PrizeRebel、百度众测、收奖网 | 注册即可 |");
add("| **3天内** | Scribie、GoTranscript、CastingWords、TranscribeMe、Figure Eight、OneForma | 简单测试 |");
add("| **1周内** | 一品威客、猪八戒、程序员客栈、猿急送、Smartcat、Unbabel | 要看活投标 |");
add("| **2周-1月** | Freelancer、Upwork、Fiverr、Toptal、99designs | 要积累信誉 |");
add("| **不确定** | 家教类、专家咨询类、赏金类 | 要资质或审核 |");
add("");
add("## 六、配套文件");
add("");
add("| 文件 | 用途 |");
add("|---|---|");
add("| **接散活平台书签-"+C.total+"个.html** | 导入 Chrome |");
add("| 接单平台每日巡检表.md | 每天照着扫 |");
add("| **`_GIG_CLEAN_FINAL.json`** | **"+C.total+" 个审计后完整数据** |");
add("| `_CN_GIG_RESULT.json` | 30 个中文平台实测原始数据 |");
add("");
add("## 七、诚实说明");
add("");
add("| 项 | 说明 |");
add("|---|---|");
add("| A 级能证明有活 | 项目数是页面快照 |");
add("| B 级没看到活 | 只确认平台存在 |");
add("| 家教/专家咨询类要看资质 | 不是人人都能做 |");
add("| 中文平台需注册 | 猪八戒/程序员客栈登录后才显示完整项目 |");
add("| 已剔除 4 个招聘性质强的 | Dribbble Jobs、TTEC、Arise、Concentrix |");
add("| 单日快照 | 2026-10-21 实测 |");
add("");
add("**累计实测候选 314 个，审计后收录 "+C.total+" 个。**");
add("");

await fs.writeFile(P2+"\\接散活平台最终清单-"+C.total+"个.md", rows.join("\n"), "utf8");
const st = await fs.stat(P2+"\\接散活平台最终清单-"+C.total+"个.md");
return { mdBytes: st.size, total: C.total, excluded: C.excluded.length };
